394	    input.memberId,
395	  );
396	  assertCan(actor, "member:update_role", memberResource(member));
397	
398	  if (!hasRoleAtLeast(actor.role, input.role)) {
399	    throw new Error(
400	      `A ${actor.role} cannot grant the ${input.role} role`,
401	    );
402	  }
403	
404	  await assertLastOwnerRetained(input.orgId, input.memberId, input.role);
405	
406	  const updated = await memberRepo.updateMemberRole(
407	    input.orgId,
408	    input.memberId,
409	    input.role,
410	  );
411	
412	  await emit("member.role_changed", {
413	    ...actorEnvelope(actor),
414	    memberId: updated.id,
415	    from: member.role,
416	    to: updated.role,
417	  });
418	
419	  return updated;
420	}
