422	/**
423	 * Removal is a soft delete, and it is subject to the same last-owner rule as a
424	 * demotion — a removed owner is a demotion to "no role at all".
425	 */
426	export async function removeMember(
427	  actor: Actor,
428	  input: RemoveMemberInput,
429	): Promise<Member> {
430	  assertOrgScope(actor, input.orgId);
431	
432	  const member = requireFound(
433	    await memberRepo.findMemberById(input.orgId, input.memberId),
434	    "Member",
435	    input.memberId,
436	  );
437	  assertCan(actor, "member:remove", memberResource(member));
438	
439	  await assertLastOwnerRetained(input.orgId, input.memberId, "member");
440	
441	  const removed = await memberRepo.archiveMember(input.orgId, input.memberId);
442	
443	  await emit("member.removed", {
444	    ...actorEnvelope(actor),
445	    memberId: removed.id,
446	    userId: removed.userId,
447	  });
448	
449	  return removed;
450	}
