452	/**
453	 * Turns a (user, org) pair into the `Actor` every service method takes. The
454	 * only place an `Actor` is minted from stored state — jobs and the session
455	 * layer both come through here.
456	 */
457	export async function resolveActor(
458	  userId: UserId,
459	  orgId: OrgId,
460	): Promise<Actor | null> {
461	  const member = await memberRepo.findMember(orgId, userId);
462	  if (!member || member.status !== "active") return null;
463	
464	  return { userId, orgId, role: member.role };
