470	 * it, and the invariant must not be stated twice.
471	 */
472	export async function assertLastOwnerRetained(
473	  orgId: OrgId,
474	  memberId: MemberId,
475	  nextRole: Role,
476	): Promise<void> {
477	  if (nextRole === "owner") return;
478	
479	  const member = await memberRepo.findMemberById(orgId, memberId);
480	  if (!member || member.role !== "owner") return;
481	
482	  const page = await memberRepo.listMembers({
483	    orgId,
484	    role: "owner",
485	    limit: OWNER_SCAN_LIMIT,
486	    cursor: null,
487	  });
488	
489	  const remaining = page.items.filter((row) => row.id !== memberId);
490	  if (remaining.length === 0) {
491	    throw new Error(
492	      "An organization must keep at least one owner; transfer ownership first",
493	    );
494	  }
495	}
