553	/** Cursor-paged member list joined with the user record the UI renders. */
554	export async function listMembers(
555	  input: ListMembersInput,
556	): Promise<Page<MemberWithUser>> {
557	  const db = getDb();
558	  const sort = { sortColumn: members.createdAt, idColumn: members.id };
559	
560	  const filters = compact(
561	    orgPredicate(members.orgId, input.orgId),
562	    liveMemberPredicate(),
563	    input.role === undefined ? undefined : eq(members.role, input.role),
564	    input.status === undefined ? undefined : eq(members.status, input.status),
565	    input.query === undefined
566	      ? undefined
567	      : or(
568	          like(users.name, `%${input.query}%`),
569	          like(users.email, `%${input.query}%`),
570	        ),
571	  );
572	
573	  const total = db
574	    .select({ value: count() })
575	    .from(members)
576	    .innerJoin(users, eq(users.id, members.userId))
577	    .where(and(...filters))
578	    .get();
579	
580	  const rows = db
581	    .select({ member: members, user: users })
582	    .from(members)
583	    .innerJoin(users, eq(users.id, members.userId))
584	    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
585	    .orderBy(desc(members.createdAt), desc(members.id))
586	    .limit(probeLimit(input.limit))
587	    .all();
588	
589	  return toPage(
590	    rows,
591	    input.limit,
592	    total?.value ?? 0,
593	    (row) => ({ ...toMember(row.member), user: toUser(row.user) }),
594	    (row) => ({ id: row.member.id, sortValue: row.member.createdAt }),
595	  );
596	}
