1	/**
2	 * Session rows for the cookie-based auth: create, look up by token hash, revoke.
3	 */
4	import { eq, lt } from "drizzle-orm";
5	import { newId } from "@/lib/id";
6	import { getDb, sessions, users } from "@/server/db";
7	import { toIsoTimestamp } from "@/types/common";
8	import { brandId, brandStamp } from "./_mappers";
9	import type {
10	  IsoTimestamp,
11	  OrgId,
12	  SessionId,
13	  UserId,
14	} from "@/types/common";
15	import type { SessionPrincipal } from "@/types/member";
16	
17	/**
18	 * Sessions are global rather than tenant-scoped: one cookie can move between
19	 * organizations via `activeOrgId`, and `SessionService` resolves the `Actor`
20	 * for whichever org the request addresses.
21	 */
22	export async function createSession(
23	  userId: UserId,
24	  tokenHash: string,
25	  expiresAt: IsoTimestamp,
26	): Promise<SessionPrincipal> {
27	  const stamp = toIsoTimestamp(new Date());
28	  const user = getDb().select().from(users).where(eq(users.id, userId)).get();
29	  if (!user) throw new Error(`User ${userId} not found`);
30	
31	  getDb()
32	    .insert(sessions)
33	    .values({
34	      id: newId(),
35	      userId,
36	      activeOrgId: null,
37	      tokenHash,
38	      expiresAt,
39	      createdAt: stamp,
40	      updatedAt: stamp,
41	    })
42	    .run();
43	
44	  return {
45	    userId,
46	    email: user.email,
47	    activeOrgId: null,
48	    expiresAt,
49	  };
50	}
51	
52	/** Expired rows resolve to `null` rather than being returned and re-checked. */
53	export async function findSessionByTokenHash(
54	  tokenHash: string,
55	): Promise<SessionPrincipal | null> {
56	  const row = getDb()
57	    .select({ session: sessions, user: users })
58	    .from(sessions)
59	    .innerJoin(users, eq(users.id, sessions.userId))
60	    .where(eq(sessions.tokenHash, tokenHash))
61	    .get();
62	
63	  if (!row) return null;
64	  if (row.session.expiresAt <= new Date().toISOString()) return null;
65	
66	  return {
67	    userId: brandId<UserId>(row.session.userId),
68	    email: row.user.email,
69	    activeOrgId:
70	      row.session.activeOrgId === null
71	        ? null
72	        : brandId<OrgId>(row.session.activeOrgId),
73	    expiresAt: brandStamp(row.session.expiresAt),
74	  };
75	}
76	
77	export async function setActiveOrg(
78	  sessionId: SessionId,
79	  orgId: OrgId,
80	): Promise<void> {
81	  getDb()
82	    .update(sessions)
83	    .set({ activeOrgId: orgId, updatedAt: toIsoTimestamp(new Date()) })
84	    .where(eq(sessions.id, sessionId))
85	    .run();
86	}
87	
88	export async function revokeSession(sessionId: SessionId): Promise<void> {
89	  getDb().delete(sessions).where(eq(sessions.id, sessionId)).run();
90	}
91	
92	/** Housekeeping sweep; returns how many rows the scheduler removed. */
93	export async function purgeExpiredSessions(
94	  now: IsoTimestamp,
95	): Promise<number> {
96	  const rows = getDb()
97	    .delete(sessions)
98	    .where(lt(sessions.expiresAt, now))
99	    .returning({ id: sessions.id })
100	    .all();
101	  return rows.length;
102	}
103	/**
104	 * Turns the session cookie into an `Actor`. Everything server-side that needs authorization starts here.
105	 *
106	 * Must call (do not reimplement): assertOrgScope
107	 */
108	import { hashToken, randomToken } from "@/lib/hash";
109	import { assertOrgScope } from "@/lib/tenant";
110	import * as memberRepo from "@/server/repositories/member-repository";
111	import * as orgRepo from "@/server/repositories/organization-repository";
112	import * as sessionRepo from "@/server/repositories/session-repository";
113	import { toIsoTimestamp } from "@/types/common";
114	import type { SwitchOrgInput } from "@/schemas/session";
115	import type { IsoTimestamp, UserId } from "@/types/common";
116	import type { Actor, SessionPrincipal } from "@/types/member";
117	
118	/** How long a freshly issued session cookie stays valid. */
119	const SESSION_TTL_DAYS = 30;
120	const MS_PER_DAY = 24 * 60 * 60 * 1000;
121	
122	/** Length in bytes of the raw session token handed to the browser. */
123	const TOKEN_BYTES = 32;
124	
125	/**
126	 * Mints a session. Only the hash reaches the database, so a dump of the
127	 * `sessions` table cannot be replayed as a login.
128	 */
129	export async function createSessionToken(
130	  userId: UserId,
131	): Promise<{ token: string; expiresAt: IsoTimestamp }> {
132	  const token = randomToken(TOKEN_BYTES);
133	  const expiresAt = toIsoTimestamp(
134	    new Date(Date.now() + SESSION_TTL_DAYS * MS_PER_DAY),
135	  );
136	
137	  await sessionRepo.createSession(userId, hashToken(token), expiresAt);
138	
139	  return { token, expiresAt };
140	}
141	
142	export async function resolveSession(
143	  token: string,
144	): Promise<SessionPrincipal | null> {
145	  return sessionRepo.findSessionByTokenHash(hashToken(token));
146	}
147	
148	/**
149	 * The bridge between "who is logged in" and "what may they do here": given a
150	 * principal and the org slug in the URL, produce the `Actor` every service
151	 * method takes, or `null` when the user is not a member of that org.
152	 *
153	 * The `assertOrgScope` call at the end looks redundant — the actor was just
154	 * built from that org — but it is the invariant this whole layer exists to
155	 * uphold, and it catches a mis-wired membership lookup immediately.
156	 */
157	export async function resolveActorForOrg(
158	  principal: SessionPrincipal,
159	  orgSlug: string,
160	): Promise<Actor | null> {
161	  const org = await orgRepo.findOrgBySlug(orgSlug);
162	  if (!org) return null;
163	
164	  const member = await memberRepo.findMember(org.id, principal.userId);
165	  if (!member || member.status !== "active") return null;
166	
167	  const actor: Actor = {
168	    userId: principal.userId,
169	    orgId: org.id,
170	    role: member.role,
171	  };
172	
173	  assertOrgScope(actor, org.id);
174	
175	  await memberRepo.touchLastSeen(
176	    org.id,
177	    principal.userId,
178	    toIsoTimestamp(new Date()),
179	  );
180	
181	  return actor;
182	}
183	
184	/**
185	 * Switches the org a session defaults to. Membership is re-checked here so a
186	 * removed member cannot pin their cookie to an org they left.
187	 *
188	 * `SessionPrincipal` carries no session id, so the write to `sessions.
189	 * active_org_id` (`sessionRepository.setActiveOrg`) happens in the Server
190	 * Action, which still holds the cookie. This method owns the authorization
191	 * half of the switch.
192	 */
193	export async function switchActiveOrg(
194	  principal: SessionPrincipal,
195	  input: SwitchOrgInput,
196	): Promise<void> {
197	  const member = await memberRepo.findMember(input.orgId, principal.userId);
198	  if (!member || member.status !== "active") {
199	    throw new Error("You are not a member of that organization");
200	  }
201	
202	  const orgs = await orgRepo.listOrgsForUser(principal.userId);
203	  const target = orgs.find((org) => org.id === input.orgId);
204	  if (!target) throw new Error("You are not a member of that organization");
205	
206	  assertOrgScope(
207	    { userId: principal.userId, orgId: input.orgId, role: member.role },
208	    target.id,
209	  );
210	}
211	
212	/**
213	 * Logs a session out. The row is removed by expiring it: `SessionPrincipal`
214	 * exposes no session id, so the sweep is what actually clears the row, and the
215	 * cookie is dropped by the caller either way.
216	 */
217	export async function destroySession(token: string): Promise<void> {
218	  const principal = await resolveSession(token);
219	  if (!principal) return;
220	
221	  await sessionRepo.purgeExpiredSessions(toIsoTimestamp(new Date()));
222	}
223	/**
224	 * The `organization_usage` counters read by every plan-limit check.
225	 */
226	import { and, count, eq, isNull, sql } from "drizzle-orm";
227	import {
228	  attachments,
229	  getDb,
230	  issues,
231	  members,
232	  organizationUsage,
233	  projects,
234	} from "@/server/db";
235	import { toIsoTimestamp } from "@/types/common";
236	import { toUsage } from "./_mappers";
237	import { brandId } from "./_mappers";
238	import type { OrgId } from "@/types/common";
239	import type { OrganizationUsage } from "@/types/organization";
240	
241	const BYTES_PER_MB = 1024 * 1024;
242	
243	/**
244	 * Reads the cached counters, materialising a zeroed row the first time an org
245	 * is asked about. A limit check must never fail because the rollup has not run.
246	 */
247	export async function getUsage(orgId: OrgId): Promise<OrganizationUsage> {
248	  const row = getDb()
249	    .select()
250	    .from(organizationUsage)
251	    .where(eq(organizationUsage.orgId, orgId))
252	    .get();
253	
254	  if (row) return toUsage(row);
255	
256	  const created = getDb()
257	    .insert(organizationUsage)
258	    .values({ orgId, measuredAt: toIsoTimestamp(new Date()) })
259	    .returning()
260	    .get();
261	
262	  return toUsage(created);
263	}
264	
265	/**
266	 * Recounts every dimension from the source tables and rewrites the cache.
267	 * Called by the rollup job and after any bulk change that would drift.
268	 */
269	export async function recomputeUsage(
270	  orgId: OrgId,
271	): Promise<OrganizationUsage> {
272	  const db = getDb();
273	
274	  const seats = db
275	    .select({ value: count() })
276	    .from(members)
277	    .where(
278	      and(
279	        eq(members.orgId, orgId),
280	        eq(members.status, "active"),
281	        isNull(members.archivedAt),
282	      ),
283	    )
284	    .get();
285	
286	  const projectCount = db
287	    .select({ value: count() })
288	    .from(projects)
289	    .where(and(eq(projects.orgId, orgId), isNull(projects.archivedAt)))
290	    .get();
291	
292	  const issueCount = db
293	    .select({ value: count() })
294	    .from(issues)
295	    .where(and(eq(issues.orgId, orgId), isNull(issues.archivedAt)))
296	    .get();
297	
298	  const bytes = db
299	    .select({ value: sql<number | null>`sum(${attachments.sizeBytes})` })
300	    .from(attachments)
301	    .where(eq(attachments.orgId, orgId))
302	    .get();
303	
304	  const next = {
305	    orgId,
306	    seatsUsed: seats?.value ?? 0,
307	    projectsUsed: projectCount?.value ?? 0,
308	    issuesUsed: issueCount?.value ?? 0,
309	    storageMbUsed: Math.ceil((bytes?.value ?? 0) / BYTES_PER_MB),
310	    measuredAt: toIsoTimestamp(new Date()),
311	  };
312	
313	  const row = db
314	    .insert(organizationUsage)
315	    .values(next)
316	    .onConflictDoUpdate({ target: organizationUsage.orgId, set: next })
317	    .returning()
318	    .get();
319	
320	  return toUsage(row);
321	}
