323	/**
324	 * Cheap delta applied on the write path so a quota check right after a create
325	 * sees the new number without waiting for the rollup.
326	 */
327	export async function incrementUsage(
328	  orgId: OrgId,
329	  patch: Partial<
330	    Pick<
331	      OrganizationUsage,
332	      "seatsUsed" | "projectsUsed" | "issuesUsed" | "storageMbUsed"
333	    >
334	  >,
335	): Promise<OrganizationUsage> {
336	  const current = await getUsage(orgId);
337	
338	  const row = getDb()
339	    .update(organizationUsage)
340	    .set({
341	      seatsUsed: current.seatsUsed + (patch.seatsUsed ?? 0),
342	      projectsUsed: current.projectsUsed + (patch.projectsUsed ?? 0),
343	      issuesUsed: current.issuesUsed + (patch.issuesUsed ?? 0),
344	      storageMbUsed: current.storageMbUsed + (patch.storageMbUsed ?? 0),
345	      measuredAt: toIsoTimestamp(new Date()),
346	    })
347	    .where(eq(organizationUsage.orgId, orgId))
348	    .returning()
349	    .get();
350	
351	  return toUsage(row);
352	}
353	
354	/** The rollup job's work list: the oldest measurements first. */
355	export async function listOrgIdsForRollup(
356	  limit: number,
357	): Promise<readonly OrgId[]> {
358	  const rows = getDb()
359	    .select({ orgId: organizationUsage.orgId })
360	    .from(organizationUsage)
361	    .orderBy(organizationUsage.measuredAt)
362	    .limit(Math.max(1, limit))
363	    .all();
364	
365	  return rows.map((row) => brandId<OrgId>(row.orgId));
366	}
367	/**
368	 * Recomputes the usage counters that every `LimitCheck` compares against.
369	 *
370	 * Must call (do not reimplement): assertOrgScope, subscribe, getPlanLimits
371	 */
372	import { getPlanLimits } from "@/config/plan-limits";
373	import { emit, subscribe } from "@/lib/event-bus";
374	import { assertOrgScope } from "@/lib/tenant";
375	import * as orgRepo from "@/server/repositories/organization-repository";
376	import * as usageRepo from "@/server/repositories/usage-repository";
377	import { toIsoTimestamp } from "@/types/common";
378	import type { OrgId } from "@/types/common";
379	import type { Unsubscribe } from "@/types/event";
380	import type { Actor } from "@/types/member";
381	import type { OrganizationUsage } from "@/types/organization";
382	
383	/** Fraction of a quota at which the "approaching limit" event fires. */
384	const WARN_THRESHOLD = 0.9;
385	
386	export async function getUsage(
387	  actor: Actor,
388	  orgId: OrgId,
389	): Promise<OrganizationUsage> {
390	  assertOrgScope(actor, orgId);
391	  return usageRepo.getUsage(orgId);
392	}
393	
394	/**
395	 * Full recount from the source tables. Called by the rollup job and by every
396	 * event that could have moved a counter — after recounting, the seat and
397	 * project totals are checked against the plan so a breach surfaces as an
398	 * event rather than waiting for the next write to be rejected.
399	 */
400	export async function recomputeUsage(
401	  orgId: OrgId,
402	): Promise<OrganizationUsage> {
403	  const usage = await usageRepo.recomputeUsage(orgId);
404	  const org = await orgRepo.findOrgById(orgId);
405	  if (!org) return usage;
406	
407	  const limits = getPlanLimits(org.plan);
408	
409	  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
410	    await emit("billing.limit_exceeded", {
411	      orgId,
412	      actorId: null,
413	      occurredAt: toIsoTimestamp(new Date()),
414	      resource: "seats",
415	      limit: limits.seats,
416	      used: usage.seatsUsed,
417	    });
418	  }
419	
420	  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
421	    await emit("billing.limit_exceeded", {
422	      orgId,
423	      actorId: null,
424	      occurredAt: toIsoTimestamp(new Date()),
425	      resource: "projects",
426	      limit: limits.projects,
427	      used: usage.projectsUsed,
428	    });
429	  }
430	
431	  return usage;
432	}
433	
434	/**
435	 * Every event that changes a counted resource nudges the cache. The deltas are
436	 * cheap; the periodic rollup is what corrects any drift they accumulate.
437	 */
438	export function registerUsageListeners(): Unsubscribe {
439	  const offs: Unsubscribe[] = [
440	    subscribe("issue.created", async (payload) => {
441	      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
442	    }),
443	    subscribe("issue.archived", async (payload) => {
444	      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
445	    }),
446	    subscribe("project.created", async (payload) => {
447	      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });
448	    }),
449	    subscribe("project.archived", async (payload) => {
450	      await usageRepo.incrementUsage(payload.orgId, {
451	        projectsUsed: -1,
452	        issuesUsed: -payload.issuesArchived,
453	      });
454	    }),
455	    subscribe("member.joined", async (payload) => {
456	      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });
457	    }),
458	    subscribe("member.removed", async (payload) => {
459	      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
460	    }),
461	  ];
462	
463	  return () => {
464	    for (const off of offs) off();
465	  };
466	}
467	/**
468	 * Builds the daily digest bundle per recipient from unread notifications inside the org's digest window.
469	 *
470	 * Must call (do not reimplement): isEnabled, renderEmail
471	 */
472	import { isEnabled } from "@/lib/feature-flags";
473	import { DIGEST_MAX_ENTRIES } from "@/config/constants";
474	import * as notificationRepo from "@/server/repositories/notification-repository";
475	import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
476	import * as orgRepo from "@/server/repositories/organization-repository";
477	import { renderEmail } from "./email-service";
478	import { buildFlagContext } from "./feature-flag-service";
479	import type { RenderedEmail } from "@/server/services/email-service";
480	import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
481	import type { User } from "@/types/member";
482	import type { DigestBundle, DigestEntry } from "@/types/notification";
483	
484	/** A digest with fewer entries than this is not worth an email. */
485	const MIN_ENTRIES = 1;
486	
487	/**
488	 * Collects one recipient's unread notifications inside the window. Returns
489	 * `null` — rather than an empty bundle — when the org's plan does not include
490	 * the digest, or when there is nothing to say: the caller treats `null` as
491	 * "send nothing", so a quiet day produces no mail at all.
492	 */
493	export async function buildDigest(
494	  orgId: OrgId,
495	  recipientId: UserId,
496	  windowStart: IsoTimestamp,
497	  windowEnd: IsoTimestamp,
498	): Promise<DigestBundle | null> {
499	  const org = await orgRepo.findOrgById(orgId);
500	  if (!org) return null;
501	
502	  if (!isEnabled("digest_email", buildFlagContext(null, org))) return null;
503	
504	  const unread = await notificationRepo.listUnreadSince(
505	    orgId,
506	    recipientId,
507	    windowStart,
508	  );
509	
510	  const entries: DigestEntry[] = unread
511	    .filter((notification) => notification.createdAt <= windowEnd)
512	    .map((notification) => ({
513	      notificationId: notification.id,
514	      kind: notification.kind,
515	      title: notification.title,
516	      href: notification.href,
517	      occurredAt: notification.createdAt,
518	    }))
519	    .slice(0, DIGEST_MAX_ENTRIES);
520	
521	  if (entries.length < MIN_ENTRIES) return null;
522	
523	  return { orgId, recipientId, entries, windowStart, windowEnd };
524	}
525	
526	/**
527	 * Who gets a digest: everyone who set at least one notification kind to
528	 * `digestOnly`. Opting into the digest is what suppresses the immediate
529	 * emails, so the two lists are two views of the same preference.
530	 */
531	export async function listDigestRecipients(
532	  orgId: OrgId,
533	): Promise<readonly UserId[]> {
534	  return preferenceRepo.listDigestSubscribers(orgId);
535	}
536	
537	/** Renders one bundle through the shared email pipeline. */
538	export async function renderDigest(
539	  bundle: DigestBundle,
540	  recipient: User,
541	): Promise<RenderedEmail> {
542	  return renderEmail("digest", {
543	    orgId: bundle.orgId,
544	    recipientName: recipient.name,
545	    entryCount: bundle.entries.length,
546	    windowStart: bundle.windowStart,
547	    windowEnd: bundle.windowEnd,
548	    headline: bundle.entries[0]?.title ?? "",
549	  });
550	}
551	/**
552	 * Builds and 'sends' the daily digest for every subscriber of every org whose digest hour has arrived.
553	 *
554	 * Must call (do not reimplement): isEnabled, buildDigest, sendEmail
555	 */
556	import { isEnabled } from "@/lib/feature-flags";
557	import { createLogger } from "@/lib/logger";
558	import * as notificationRepo from "@/server/repositories/notification-repository";
559	import * as orgRepo from "@/server/repositories/organization-repository";
560	import * as usageRepo from "@/server/repositories/usage-repository";
561	import * as userRepo from "@/server/repositories/user-repository";
562	import { buildDigest, listDigestRecipients, renderDigest } from "@/server/services/digest-service";
563	import { sendEmail } from "@/server/services/email-service";
564	import { buildFlagContext } from "@/server/services/feature-flag-service";
565	import { toIsoTimestamp } from "@/types/common";
566	import { runJob } from "./types";
567	import type { JobResult } from "@/server/jobs/types";
568	import type { Organization } from "@/types/organization";
569	
570	const ORG_BATCH = 50;
571	const MS_PER_DAY = 24 * 60 * 60 * 1000;
572	
573	const logger = createLogger("digest-email-job");
574	
575	/**
576	 * One pass per scheduler tick. Each org is only processed during the UTC hour
577	 * it configured, so a tick that runs every few minutes still sends exactly one
578	 * digest per day per recipient.
579	 */
580	export async function runDigestEmailJob(now: Date): Promise<JobResult> {
581	  return runJob("digest-email", async (result) => {
582	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
583	
584	    for (const orgId of orgIds) {
585	      const org = await orgRepo.findOrgById(orgId);
586	      if (!org || !shouldRunForOrg(org, now)) continue;
587	
588	      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;
589	
590	      const windowEnd = toIsoTimestamp(now);
591	      const windowStart = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));
592	
593	      for (const recipientId of await listDigestRecipients(orgId)) {
594	        try {
595	          const bundle = await buildDigest(
596	            orgId,
597	            recipientId,
598	            windowStart,
599	            windowEnd,
600	          );
601	          if (!bundle) continue;
602	
603	          const recipient = await userRepo.findUserById(recipientId);
604	          if (!recipient) continue;
605	
606	          const rendered = await renderDigest(bundle, recipient);
607	          await sendEmail({ to: recipient.email, ...rendered });
608	
609	          // Once digested, these notifications are no longer "unread" — this
610	          // is what keeps a later run inside the same window from sending
611	          // the same digest twice.
612	          for (const entry of bundle.entries) {
613	            await notificationRepo.markRead(orgId, entry.notificationId, windowEnd);
614	          }
615	
616	          result.processed += 1;
617	        } catch (error) {
618	          result.failed += 1;
619	          logger.error("digest failed", {
620	            orgId,
621	            recipientId,
622	            reason: error instanceof Error ? error.message : String(error),
623	          });
624	        }
625	      }
626	    }
627	  });
628	}
629	
630	/**
631	 * True during the org's configured digest hour. Exported because the schedule
632	 * decision is worth testing on its own, without a database.
633	 */
634	export function shouldRunForOrg(org: Organization, now: Date): boolean {
635	  if (org.archivedAt !== null) return false;
636	  return now.getUTCHours() === org.settings.digestHourUtc;
637	}
638	/**
639	 * The fan-out hub: one domain event becomes in-app rows, an email draft and/or a digest entry, filtered by each recipient's preferences.
640	 *
641	 * Must call (do not reimplement): assertCan, assertOrgScope, isEnabled, subscribe
642	 */
643	import { subscribe } from "@/lib/event-bus";
644	import { isEnabled } from "@/lib/feature-flags";
645	import { assertCan } from "@/lib/permissions";
646	import { assertOrgScope } from "@/lib/tenant";
647	import * as issueRepo from "@/server/repositories/issue-repository";
648	import * as notificationRepo from "@/server/repositories/notification-repository";
649	import * as orgRepo from "@/server/repositories/organization-repository";
650	import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
651	import { toIsoTimestamp } from "@/types/common";
652	import { notificationResource, requireFound } from "./_support";
653	import type {
654	  ListNotificationsInput,
655	  MarkNotificationReadInput,
656	  UpdateNotificationPreferenceInput,
657	} from "@/schemas/notification";
658	import type { OrgId, Page, UserId } from "@/types/common";
659	import type { FlagContext } from "@/types/feature-flag";
660	import type { Actor } from "@/types/member";
661	import type {
662	  Notification,
663	  NotificationChannel,
664	  NotificationKind,
665	  NotificationPreference,
666	} from "@/types/notification";
667	
668	export type NotificationPayload = {
669	  title: string;
670	  body: string;
671	  href: string;
672	  actorId: UserId | null;
673	};
674	
675	/** Channels used when a recipient has never touched their preferences. */
676	const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];
677	
678	/**
679	 * Writes one notification row per recipient, each with the channel set that
680	 * recipient's preferences allow. A recipient who has muted every channel is
681	 * skipped entirely rather than given a row nobody will ever see.
682	 */
683	export async function notify(
684	  orgId: OrgId,
685	  kind: NotificationKind,
686	  recipients: readonly UserId[],
687	  payload: NotificationPayload,
688	): Promise<readonly Notification[]> {
689	  if (recipients.length === 0) return [];
690	
691	  const org = await orgRepo.findOrgById(orgId);
692	  const flags: FlagContext = {
693	    orgId,
694	    userId: payload.actorId,
695	    plan: org?.plan ?? "free",
696	    role: null,
697	    overrides: org?.settings.enabledFlagOverrides,
698	  };
699	
700	  const rows = [];
701	
702	  for (const recipientId of new Set(recipients)) {
703	    if (recipientId === payload.actorId) continue;
704	
705	    const preference = await preferenceRepo.getPreference(
706	      orgId,
707	      recipientId,
708	      kind,
709	    );
710	    const channels = resolveChannels(preference, flags);
711	    if (channels.length === 0) continue;
712	
713	    rows.push({
714	      orgId,
715	      recipientId,
716	      kind,
717	      title: payload.title,
718	      body: payload.body,
719	      href: payload.href,
720	      actorId: payload.actorId,
721	      channels,
722	    });
723	  }
724	
725	  return notificationRepo.insertNotifications(orgId, rows);
726	}
727	
728	export async function listNotifications(
729	  actor: Actor,
730	  input: ListNotificationsInput,
731	): Promise<Page<Notification>> {
732	  assertOrgScope(actor, input.orgId);
733	  assertCan(
734	    actor,
735	    "notification:read",
736	    notificationResource(input.orgId, input.recipientId),
737	  );
738	  return notificationRepo.listNotifications(input);
739	}
740	
741	export async function markRead(
742	  actor: Actor,
743	  input: MarkNotificationReadInput,
744	): Promise<Notification> {
745	  assertOrgScope(actor, input.orgId);
746	  assertCan(
747	    actor,
748	    "notification:manage",
749	    notificationResource(input.orgId, actor.userId),
750	  );
751	  return notificationRepo.markRead(
752	    input.orgId,
753	    input.notificationId,
754	    toIsoTimestamp(new Date()),
755	  );
756	}
757	
758	export async function markAllRead(
759	  actor: Actor,
760	  orgId: OrgId,
761	): Promise<number> {
762	  assertOrgScope(actor, orgId);
763	  assertCan(
764	    actor,
765	    "notification:manage",
766	    notificationResource(orgId, actor.userId),
767	  );
768	  return notificationRepo.markAllRead(
769	    orgId,
770	    actor.userId,
771	    toIsoTimestamp(new Date()),
772	  );
773	}
774	
775	export async function updatePreference(
776	  actor: Actor,
777	  input: UpdateNotificationPreferenceInput,
778	): Promise<NotificationPreference> {
779	  assertOrgScope(actor, input.orgId);
780	  assertCan(
781	    actor,
782	    "notification:manage",
783	    notificationResource(input.orgId, input.userId),
784	  );
785	  return preferenceRepo.upsertPreference(input);
786	}
787	
788	/**
789	 * Turns a stored preference into the channels one notification will use.
790	 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
791	 * the email channel additionally requires the org's `digest_email` plan flag.
792	 */
793	export function resolveChannels(
794	  preference: NotificationPreference | null,
795	  flags: FlagContext,
796	): readonly NotificationChannel[] {
797	  if (preference === null) return DEFAULT_CHANNELS;
798	
799	  const channels: NotificationChannel[] = [];
800	  if (preference.inApp) channels.push("in_app");
801	
802	  const emailAllowed =
803	    preference.email &&
804	    (!preference.digestOnly || isEnabled("digest_email", flags));
805	
806	  if (emailAllowed) channels.push("email");
807	  return channels;
808	}
809	
810	/**
811	 * The bus wiring. Attached at module load rather than from `event-registry`
812	 * because the fan-out has no other public entry point — importing this module
813	 * is what makes an org start receiving notifications.
814	 */
815	let registered = false;
816	
817	function registerFanOut(): void {
818	  if (registered) return;
819	  registered = true;
820	
821	  subscribe("issue.assigned", async (payload) => {
822	    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
823	      title: "You were assigned an issue",
824	      body: `Issue ${payload.issueId} is now yours`,
825	      href: `/issues/${payload.issueId}`,
826	      actorId: payload.actorId,
827	    });
828	  });
829	
830	  subscribe("issue.overdue", async (payload) => {
831	    if (payload.assigneeId === null) return;
832	    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
833	      title: "An issue is overdue",
834	      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
835	      href: `/issues/${payload.issueId}`,
836	      actorId: null,
837	    });
838	  });
839	
840	  subscribe("comment.created", async (payload) => {
841	    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
842	    const watchers = issue
843	      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
844	      : [];
845	
846	    await notify(payload.orgId, "comment_created", watchers, {
847	      title: "New comment",
848	      body: `A comment was added to issue ${payload.issueId}`,
849	      href: `/issues/${payload.issueId}`,
850	      actorId: payload.actorId,
851	    });
852	
853	    if (payload.mentionedUserIds.length > 0) {
854	      await notify(
855	        payload.orgId,
856	        "comment_mention",
857	        payload.mentionedUserIds,
858	        {
859	          title: "You were mentioned",
860	          body: `You were mentioned on issue ${payload.issueId}`,
861	          href: `/issues/${payload.issueId}`,
862	          actorId: payload.actorId,
863	        },
864	      );
865	    }
866	  });
867	
868	  subscribe("member.joined", async (payload) => {
869	    const org = requireFound(
870	      await orgRepo.findOrgById(payload.orgId),
871	      "Organization",
872	      payload.orgId,
873	    );
874	    await notify(payload.orgId, "member_joined", [org.ownerId], {
875	      title: "A new member joined",
876	      body: `${payload.userId} joined as ${payload.role}`,
877	      href: "/settings/members",
878	      actorId: payload.userId,
879	    });
880	  });
881	}
882	
883	registerFanOut();
884	/**
885	 * Wires every subscriber at process start. Called once from `src/instrumentation.ts`; the only module that knows the full listener set.
886	 *
887	 * Must call (do not reimplement): subscribe, registerActivityListeners, registerSearchListeners, registerUsageListeners, registerWebhookListeners
888	 */
889	import { subscribe } from "@/lib/event-bus";
890	import { createLogger } from "@/lib/logger";
891	import { enqueue } from "@/server/jobs/queue";
892	import { toIsoTimestamp } from "@/types/common";
893	import { registerActivityListeners } from "./activity-service";
894	import { registerSearchListeners } from "./search-service";
895	import { registerUsageListeners } from "./usage-service";
896	import { registerWebhookListeners } from "./webhook-service";
897	import type { Unsubscribe } from "@/types/event";
898	
899	/**
900	 * Importing this module also loads `notification-service` transitively, which
901	 * attaches the notification fan-out on first import — that hub has no
902	 * `register*` entry point of its own.
903	 */
904	import "./notification-service";
905	
906	const logger = createLogger("event-registry");
907	
908	/** Non-null between `registerEventHandlers()` and `unregisterEventHandlers()`. */
909	let detach: Unsubscribe | null = null;
910	
911	/**
912	 * Attaches every subscriber exactly once. Idempotent: `instrumentation.ts`
913	 * runs per server process, but a hot reload in dev can call it again and must
914	 * not double-deliver every event.
915	 */
916	export function registerEventHandlers(): void {
917	  if (detach !== null) return;
918	
919	  const offs: Unsubscribe[] = [
920	    registerActivityListeners(),
921	    registerSearchListeners(),
922	    registerUsageListeners(),
923	    registerWebhookListeners(),
924	    registerDigestBridge(),
925	  ];
926	
927	  detach = () => {
928	    for (const off of offs) off();
929	  };
930	
931	  logger.info("event handlers registered", { groups: offs.length });
932	}
933	
934	export function unregisterEventHandlers(): void {
935	  detach?.();
936	  detach = null;
937	}
938	
939	/**
940	 * The one piece of wiring that belongs to no single service: turning a
941	 * `digest.due` event into a queued job. Keeping it here rather than inside
942	 * `DigestService` stops the service layer from depending on the job layer.
943	 */
944	function registerDigestBridge(): Unsubscribe {
945	  return subscribe("digest.due", (payload) => {
946	    enqueue({
947	      id: `digest:${payload.orgId}:${payload.recipientId}`,
948	      kind: "digest-email",
949	      runAt: toIsoTimestamp(new Date()),
950	      attempts: 0,
951	      payload: {
952	        orgId: payload.orgId,
953	        recipientId: payload.recipientId,
954	        windowStart: payload.windowStart,
955	      },
956	    });
957	  });
958	}
959	import type { LimitedResource, PlanId } from "@/types/billing";
960	import type { FeatureFlagKey } from "@/types/feature-flag";
961	
962	/**
963	 * The one place plan quotas are declared.
964	 *
965	 * `BillingService`, the invite flow, the project-create action, the webhook
966	 * settings page, the usage meter component and the seat-limit job all read
967	 * their numbers from here via `getPlanLimits()`. Adding a field to
968	 * `PlanLimits` therefore ripples into every one of those call sites — that
969	 * ripple is intentional and is what keeps the quotas honest.
970	 */
971	export interface PlanLimits {
972	  readonly plan: PlanId;
973	  readonly seats: number;
974	  readonly projects: number;
975	  readonly issuesPerProject: number;
976	  readonly storageMb: number;
977	  readonly apiRequestsPerHour: number;
978	  readonly webhooks: number;
979	  readonly retentionDays: number;
980	  readonly includedFlags: readonly FeatureFlagKey[];
981	  readonly priceCentsPerSeatMonthly: number;
982	}
983	
984	/** `Infinity` is the sanctioned representation of "no limit". */
985	export const UNLIMITED = Number.POSITIVE_INFINITY;
986	
987	export const PLAN_LIMITS: Readonly<Record<PlanId, PlanLimits>> = {
988	  free: {
989	    plan: "free",
990	    seats: 3,
991	    projects: 2,
992	    issuesPerProject: 100,
993	    storageMb: 100,
994	    apiRequestsPerHour: 100,
995	    webhooks: 0,
996	    retentionDays: 30,
997	    includedFlags: ["command_palette"],
998	    priceCentsPerSeatMonthly: 0,
999	  },
1000	  starter: {
1001	    plan: "starter",
1002	    seats: 10,
1003	    projects: 10,
1004	    issuesPerProject: 1_000,
1005	    storageMb: 2_000,
1006	    apiRequestsPerHour: 1_000,
1007	    webhooks: 2,
1008	    retentionDays: 90,
1009	    includedFlags: ["command_palette", "kanban_board", "csv_export"],
1010	    priceCentsPerSeatMonthly: 900,
1011	  },
1012	  growth: {
1013	    plan: "growth",
1014	    seats: 50,
1015	    projects: 100,
1016	    issuesPerProject: 10_000,
1017	    storageMb: 20_000,
1018	    apiRequestsPerHour: 10_000,
1019	    webhooks: 10,
1020	    retentionDays: 365,
1021	    includedFlags: [
1022	      "command_palette",
1023	      "kanban_board",
1024	      "csv_export",
1025	      "activity_feed",
1026	      "digest_email",
1027	      "webhooks",
1028	      "issue_templates",
1029	    ],
1030	    priceCentsPerSeatMonthly: 1_900,
1031	  },
1032	  enterprise: {
1033	    plan: "enterprise",
1034	    seats: UNLIMITED,
1035	    projects: UNLIMITED,
1036	    issuesPerProject: UNLIMITED,
1037	    storageMb: 500_000,
1038	    apiRequestsPerHour: 100_000,
1039	    webhooks: UNLIMITED,
1040	    retentionDays: 2_555,
1041	    includedFlags: [
1042	      "command_palette",
1043	      "kanban_board",
1044	      "csv_export",
1045	      "activity_feed",
1046	      "digest_email",
1047	      "webhooks",
1048	      "issue_templates",
1049	      "advanced_search",
1050	      "public_projects",
1051	      "ai_issue_summary",
1052	    ],
1053	    priceCentsPerSeatMonthly: 3_900,
1054	  },
1055	};
1056	
1057	/** Plans ordered cheapest → richest; used for "at least this plan" checks. */
1058	export const PLAN_ORDER: readonly PlanId[] = [
1059	  "free",
1060	  "starter",
1061	  "growth",
1062	  "enterprise",
1063	];
1064	
1065	export function getPlanLimits(plan: PlanId): PlanLimits {
1066	  return PLAN_LIMITS[plan];
1067	}
1068	
1069	/** Reads one numeric quota without the caller destructuring `PlanLimits`. */
1070	export function getLimit(plan: PlanId, resource: LimitedResource): number {
1071	  return getPlanLimits(plan)[resource];
1072	}
1073	
1074	/** True when `plan` is at least as rich as `minPlan`. */
1075	export function planAtLeast(plan: PlanId, minPlan: PlanId): boolean {
1076	  return PLAN_ORDER.indexOf(plan) >= PLAN_ORDER.indexOf(minPlan);
1077	}
1078	
1079	/** True when consuming `requested` more units would breach the quota. */
1080	export function wouldExceedLimit(
1081	  plan: PlanId,
1082	  resource: LimitedResource,
1083	  used: number,
1084	  requested = 1,
1085	): boolean {
1086	  return used + requested > getLimit(plan, resource);
1087	}
1088	/**
1089	 * Cross-cutting constants that are neither plan limits nor flags (page sizes,
1090	 * edit windows, retry counts).
1091	 *
1092	 * Quotas live in `@/config/plan-limits` and rollout gates in
1093	 * `@/config/feature-flags`; anything that is neither — a default page size, a
1094	 * grace window, a retry budget — belongs here so the number exists once.
1095	 */
1096	
1097	/** Rows per page for every cursor-paginated list unless the caller overrides. */
1098	export const DEFAULT_PAGE_SIZE: number = 25;
1099	
1100	/** Upper bound the pagination schemas clamp `limit` to. */
1101	export const MAX_PAGE_SIZE: number = 100;
1102	
1103	/** How long after posting a comment its author may still edit it. */
1104	export const COMMENT_EDIT_WINDOW_MINUTES: number = 15;
1105	
1106	/** Delivery attempts before the webhook dispatcher parks a delivery. */
1107	export const WEBHOOK_MAX_ATTEMPTS: number = 5;
1108	
1109	/** Hard cap on entries rendered in one digest email. */
1110	export const DIGEST_MAX_ENTRIES: number = 50;
1111	
1112	/** How far ahead the overdue job looks when collecting due issues. */
1113	export const OVERDUE_LOOKAHEAD_HOURS: number = 24;
