269	export async function recomputeUsage(
270	  orgId: OrgId,
271	): Promise<OrganizationUsage> {
272	  const db = getDb();
273	
274	  const seats = db
275	    .select({ value: count() })
276	    .from(members)
277	    .where(
278	      and(
279	        eq(members.orgId, orgId),
280	        eq(members.status, "active"),
281	        isNull(members.archivedAt),
282	      ),
283	    )
284	    .get();
