487	/**
488	 * Collects one recipient's unread notifications inside the window. Returns
489	 * `null` — rather than an empty bundle — when the org's plan does not include
490	 * the digest, or when there is nothing to say: the caller treats `null` as
491	 * "send nothing", so a quiet day produces no mail at all.
492	 */
493	export async function buildDigest(
494	  orgId: OrgId,
495	  recipientId: UserId,
496	  windowStart: IsoTimestamp,
497	  windowEnd: IsoTimestamp,
498	): Promise<DigestBundle | null> {
499	  const org = await orgRepo.findOrgById(orgId);
500	  if (!org) return null;
501	
502	  if (!isEnabled("digest_email", buildFlagContext(null, org))) return null;
503	
504	  const unread = await notificationRepo.listUnreadSince(
505	    orgId,
506	    recipientId,
507	    windowStart,
508	  );
509	
510	  const entries: DigestEntry[] = unread
511	    .filter((notification) => notification.createdAt <= windowEnd)
512	    .map((notification) => ({
513	      notificationId: notification.id,
514	      kind: notification.kind,
515	      title: notification.title,
516	      href: notification.href,
517	      occurredAt: notification.createdAt,
518	    }))
519	    .slice(0, DIGEST_MAX_ENTRIES);
520	
521	  if (entries.length < MIN_ENTRIES) return null;
522	
523	  return { orgId, recipientId, entries, windowStart, windowEnd };
524	}
