402	/**
403	 * The signed-in principal, or `null` when there is no cookie, the token is
404	 * unknown, or the session has expired. Callers that need a hard failure use
405	 * `getActor()` in `@/lib/actor` instead.
406	 */
407	export async function getSessionPrincipal(): Promise<SessionPrincipal | null> {
408	  const token = await getSessionToken();
409	  if (token === null) return null;
410	
411	  const principal = await resolveSession(token);
412	  if (principal === null) return null;
413	
414	  return parseIso(principal.expiresAt).getTime() > Date.now() ? principal : null;
415	}
