417	export async function setSessionCookie(
418	  token: string,
419	  expiresAt: IsoTimestamp,
420	): Promise<void> {
421	  const jar = await cookies();
422	  jar.set(SESSION_COOKIE_NAME, token, {
423	    httpOnly: true,
424	    sameSite: "lax",
425	    secure: process.env.NODE_ENV === "production",
426	    path: "/",
427	    expires: parseIso(expiresAt),
428	  });
429	}
