}

/**
 * The one path that mints invitation rows. Every refusal happens before the
 * first write, so a refused batch leaves nothing behind.
 *
 * `replacing` is the invitation a re-send supersedes: it is ignored by the
 * duplicate and seat checks (the new row takes its place) and withdrawn just
 * before the replacement is written.
 */
async function issueInvitations(
  actor: Actor,
  orgId: OrgId,
  invites: readonly { readonly email: string; readonly role: Role }[],
  replacing: InvitationId | null,
): Promise<readonly Invitation[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "member:invite", orgResource(orgId));

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  if (org.archivedAt !== null) {
    throw new Error("That organization has been deleted");
  }

  const memberEmails = new Set(await memberRepo.listCurrentMemberEmails(orgId));
  const pending = (await invitationRepo.listPendingInvitations(orgId)).filter(
    (row) => row.id !== replacing,
  );
  const pendingEmails = new Set(pending.map((row) => normalizeEmail(row.email)));

  const batchEmails = new Set<string>();
  for (const invite of invites) {
    const email = normalizeEmail(invite.email);

    if (batchEmails.has(email)) {
      throw new Error(
        `Duplicate address: ${invite.email} is named more than once in this batch`,
      );
    }
    batchEmails.add(email);

    if (memberEmails.has(email)) {
      throw new Error(
        `${invite.email} is already a member of this organization`,
      );
    }
    if (pendingEmails.has(email)) {
      throw new Error(`${invite.email} already has a pending invitation`);
    }
  }

  const verdict = await consumeRateLimit(orgId, INVITE_BUCKET, invites.length);
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  // Seats in use: the current members plus the invitations still pending.
  const seatsUsed =
    (await memberRepo.countActiveMembers(orgId)) + pending.length;

  if (wouldExceedLimit(org.plan, "seats", seatsUsed, invites.length)) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }

  if (replacing !== null) {
    await invitationRepo.revokeInvitation(orgId, replacing);
  }

  const invitations: Invitation[] = [];

  for (const invite of invites) {
    const token = randomToken(32);
    const invitation = await invitationRepo.insertInvitation(
      orgId,
      {
        orgId,
        email: invite.email,
        role: invite.role,
        expiresInDays: DEFAULT_EXPIRY_DAYS,
      },
      actor.userId,
      hashToken(token),
    );

    invitations.push(invitation);

    await emit("member.invited", {
      orgId,
      actorId: actor.userId,
      occurredAt: invitation.createdAt,
      email: invite.email,
      role: invite.role,
    });
  }

  return invitations;
}

/**
 * Accepting has no `Actor` — the person is not a member yet — so every check
 * comes off the stored row. The token alone is not enough: the invitation
 * belongs to the address it was sent to, and only that account may use it.
 */
export async function acceptInvitation(
  userId: UserId,
  input: AcceptInvitationTokenInput,
): Promise<Member> {
  const invitation = requireFound(
    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
    "Invitation",
    "token",
  );

  const now = toIsoTimestamp(new Date());

  if (invitation.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (invitation.expiresAt <= now) {
    throw new Error("That invitation has expired");
  }

  const org = await orgRepo.findOrgById(invitation.orgId);
  if (!org || org.archivedAt !== null) {
    throw new Error("That invitation's organization no longer exists");
  }

  const user = await userRepo.findUserById(userId);
  if (!user || normalizeEmail(user.email) !== normalizeEmail(invitation.email)) {
    throw new Error("That invitation was sent to a different email address");
  }

  const previous = await memberRepo.findMembershipIncludingRemoved(
    invitation.orgId,
    userId,
  );

  // Already in the org: there is nothing to join, but the link is used up.
  if (previous && previous.archivedAt === null) {
    await invitationRepo.markInvitationAccepted(
      invitation.orgId,
      invitation.id,
      now,
    );
    return previous;
  }

  // A former member gets their old membership back rather than a second row.
  const member = previous
    ? await memberRepo.restoreMember(
        invitation.orgId,
        previous.id,
        invitation.role,
        invitation.invitedBy,
        now,
      )
    : await memberRepo.insertMember(
        invitation.orgId,
        userId,
        invitation.role,
        invitation.invitedBy,
        now,
      );

  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    now,
  );

  await usageRepo.recountSeats(invitation.orgId);

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

export async function revokeInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertCan(actor, "member:invite", orgResource(actor.orgId));

  const invitation = requireFound(
    await invitationRepo.findInvitationById(actor.orgId, invitationId),
    "Invitation",
    invitationId,
  );
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (invitation.revokedAt !== null) return invitation;

  return invitationRepo.revokeInvitation(actor.orgId, invitationId);
}

/**
 * Re-sending withdraws the old link and issues a new one to the same address
 * with the same role, valid for the full period again. An expired invitation
 * can be re-sent — that is the usual reason to — but one that was accepted or
 * revoked cannot.
 */
export async function resendInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertOrgScope(actor, actor.orgId);
  assertCan(actor, "member:invite", orgResource(actor.orgId));

  const previous = requireFound(
    await invitationRepo.findInvitationById(actor.orgId, invitationId),
    "Invitation",
    invitationId,
  );

  if (previous.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (previous.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }

  const [invitation] = await issueInvitations(
    actor,
    actor.orgId,
    [{ email: previous.email, role: previous.role }],
    previous.id,
  );

  if (!invitation) throw new Error("Invitation was not created");
  return invitation;
}
